begin;
\ir fixtures/clinical.sql
select pg_temp.put('contact_patient2',public.doctor_write_patient(p_practice=>pg_temp.practice(),p_location=>pg_temp.location(),p_input=>'{"name":"Synthetic contact patient B","phone":"","email":"","date_of_birth":null}',p_key=>pg_temp.id(3000)));
select pg_temp.command('create',jsonb_build_object('patient_id',pg_temp.patient(),'snapshot',pg_temp.snapshot()),3001);
select ok(pg_temp.detail()::text like'%Synthetic entered note%','private note exists before contact projection test');
reset role;
update public.memberships set capabilities=array['patients.read','patients.write']where id=pg_temp.id(201);
update public.membership_locations set capabilities=array['patients.read','patients.write']where membership_id=pg_temp.id(201);
create function pg_temp.contact(action text,n integer,ver integer,k integer,input jsonb,patient uuid default pg_temp.patient())returns jsonb language sql as $$select public.doctor_contact_command(pg_temp.practice(),pg_temp.location(),patient,pg_temp.id(n),ver,action,input,pg_temp.id(k))$$;
create function pg_temp.preferences(patient uuid default pg_temp.patient())returns jsonb language sql as $$select public.doctor_contact_preferences(pg_temp.practice(),pg_temp.location(),patient,0,0)$$;
create function pg_temp.contact_input()returns jsonb language sql immutable as $$select '{"channel":"sms","destination":"+15550001234","recipient_kind":"patient","guardian_id":null}'::jsonb$$;
create function pg_temp.consent_input(contact integer,purpose text default'appointment_reminder')returns jsonb language sql as $$select jsonb_build_object('contact_id',pg_temp.id(contact),'contact_version',1,'purpose',purpose,'source_ref','Synthetic explicit source receipt','source_day',(clock_timestamp()at time zone'Etc/UTC'-interval'1 minute')::date,'source_minute',extract(hour from clock_timestamp()at time zone'Etc/UTC'-interval'1 minute')::integer*60+extract(minute from clock_timestamp()at time zone'Etc/UTC'-interval'1 minute')::integer,'location_version',1)$$;
create function pg_temp.guardian_input()returns jsonb language sql as $$select jsonb_build_object('purposes',jsonb_build_array('appointment_reminder'),'source_ref','Synthetic owner relationship review','expiry_day',(clock_timestamp()at time zone'Etc/UTC')::date+1,'expiry_minute',540,'location_version',1)$$;
create function pg_temp.intent(contact integer,consent_version integer,guardian_version integer default null)returns jsonb language sql immutable as $$select jsonb_build_object('contact_id',pg_temp.id(contact),'contact_version',1,'purpose','appointment_reminder','consent_version',consent_version,'guardian_version',guardian_version)$$;
create function pg_temp.eligible(intent jsonb,patient uuid default pg_temp.patient())returns jsonb language sql as $$select public.doctor_contact_eligibility(pg_temp.practice(),pg_temp.location(),patient,intent)$$;
set local role authenticated;select pg_temp.claim(1);
select is(pg_temp.contact('create_contact',3100,0,3200,pg_temp.contact_input())->>'version','1','C01: direct contact recorded independently of Auth');
select is(pg_temp.contact('create_contact',3100,0,3200,pg_temp.contact_input())->>'version','1','same creation receipt adds no contact');
select is(pg_temp.contact('create_contact',3101,0,3201,pg_temp.contact_input(),(pg_temp.v('contact_patient2')->>'patient_id')::uuid)->>'version','1','two patients may share the same destination');
select is(pg_temp.preferences()->>'contact_total','1','contact destination is not an identity merge key');
select is(pg_temp.preferences()#>'{contacts,0,consents}','[]'::jsonb,'all purposes including marketing start off');
select ok(pg_temp.preferences()::text not like'%Synthetic entered note%','contact projection excludes the persisted clinical note');
select throws_ok($$select pg_temp.contact('create_contact',3102,0,3202,pg_temp.contact_input()||'{"login_user_id":"someone"}')$$,'22023','DOCTOR_CONTACT_INVALID','contact cannot bind login identity');
select throws_ok($$select pg_temp.contact('create_contact',3102,0,3202,pg_temp.contact_input()||'{"destination":"not-a-phone"}')$$,'22023','DOCTOR_CONTACT_INVALID','channel format validated');
select is(pg_temp.contact('grant_consent',3110,0,3210,pg_temp.consent_input(3100))->>'version','1','purpose consent recorded with explicit source clock');
select throws_ok($$select pg_temp.contact('grant_consent',3150,0,3400,pg_temp.consent_input(3100,'administrative_follow_up')||jsonb_build_object('source_day',(clock_timestamp()at time zone'Etc/UTC')::date+1))$$,'22023','DOCTOR_CONTACT_INVALID','future claimed source time is not fabricated');
select throws_ok($$select pg_temp.contact('grant_consent',3150,0,3401,pg_temp.consent_input(3100,'administrative_follow_up')||'{"location_version":99}')$$,'40001','DOCTOR_CONTACT_CONFLICT','source clock requires captured clinic version');
select throws_ok($$select pg_temp.contact('grant_consent',3150,0,3402,pg_temp.consent_input(3100,'administrative_follow_up')||'{"legal_approval":true}')$$,'22023','DOCTOR_CONTACT_INVALID','caller cannot manufacture legal approval metadata');

select is(pg_temp.eligible(pg_temp.intent(3100,1))->>'eligible','true','exact captured direct-contact intent eligible only for synthetic preparation');
select is(pg_temp.eligible(pg_temp.intent(3101,1),(pg_temp.v('contact_patient2')->>'patient_id')::uuid)->>'eligible','false','shared destination never shares consent');
select is(pg_temp.preferences()->>'legal_approval','false','stored source never creates legal approval');
select is(pg_temp.preferences()->>'external_messages','disabled','no external dispatch in contact feature');
select is(pg_temp.contact('revoke_consent',3110,1,3211,'{"source_ref":"Synthetic withdrawal received"}')->>'version','2','C03: withdrawal immediately changes consent version');
select is(pg_temp.eligible(pg_temp.intent(3100,1))->>'blocker','consent_unavailable','prepared intent suppressed after channel-purpose withdrawal');
select is(pg_temp.contact('grant_consent',3110,2,3212,pg_temp.consent_input(3100))->>'version','3','new explicit source may record new consent');
select is(pg_temp.eligible(pg_temp.intent(3100,1))->>'eligible','false','renewal cannot resurrect older prepared consent intent');
select is(pg_temp.eligible(pg_temp.intent(3100,3))->>'eligible','true','new intent must capture the new consent version');
select throws_ok($$select pg_temp.contact('grant_consent',3110,1,3213,pg_temp.consent_input(3100))$$,'40001','DOCTOR_CONTACT_CONFLICT','stale consent mutation denied');
select is(pg_temp.contact('create_guardian',3120,0,3220,'{"label":"Synthetic guardian A","relationship":"parent","source_ref":"Synthetic entered relationship"}')->>'version','1','guardian relationship begins unreviewed');
select throws_ok($$select pg_temp.contact('create_contact',3121,0,3221,pg_temp.contact_input()||jsonb_build_object('recipient_kind','guardian','guardian_id',pg_temp.id(3120)))$$,'42501','DOCTOR_ACCESS_DENIED','unreviewed relationship grants no contact authority');
select pg_temp.claim(3);
select throws_ok($$select pg_temp.contact('review_guardian',3120,1,3222,pg_temp.guardian_input())$$,'42501','DOCTOR_ACCESS_DENIED','administrative writer cannot forge owner review');
select pg_temp.claim(1);
select throws_ok($$select pg_temp.contact('review_guardian',3120,1,3403,pg_temp.guardian_input()||'{"expiry_minute":1440}')$$,'22023','DOCTOR_CONTACT_INVALID','guardian expiry cannot guess the next local day');
select is(pg_temp.contact('review_guardian',3120,1,3223,pg_temp.guardian_input())->>'version','2','C02: stored owner explicitly records scoped expiring synthetic review');
select is(pg_temp.preferences()#>>'{guardians,0,authority_mode}','synthetic_review_only','review record explicitly excludes live authority');
select is(pg_temp.preferences()#>>'{guardians,0,live_authority}','false','guardian review does not activate real authority');
select is(public.doctor_contact_guardian_options(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),0,'Synthetic')->>'total','1','only current reviewed relationships offered');
select is(pg_temp.contact('create_contact',3121,0,3224,pg_temp.contact_input()||jsonb_build_object('recipient_kind','guardian','guardian_id',pg_temp.id(3120)))->>'version','1','reviewed relationship explicitly selected for contact');
select throws_ok($$select pg_temp.contact('grant_consent',3122,0,3225,pg_temp.consent_input(3121,'administrative_follow_up'))$$,'42501','DOCTOR_ACCESS_DENIED','guardian purpose scope is enforced');
select is(pg_temp.contact('grant_consent',3122,0,3226,pg_temp.consent_input(3121))->>'version','1','guardian consent captures the exact relationship version');
select is(pg_temp.eligible(pg_temp.intent(3121,1,2))->>'eligible','true','current reviewed guardian and consent allow synthetic preparation');
select is(pg_temp.contact('revoke_guardian',3120,2,3227,'{"source_ref":"Synthetic relationship withdrawn"}')->>'version','3','guardian withdrawal preserves relationship history');
select is(pg_temp.eligible(pg_temp.intent(3121,1,2))->>'blocker','guardian_unavailable','prepared intent suppressed after guardian revocation');
select is(pg_temp.contact('review_guardian',3120,3,3228,pg_temp.guardian_input())->>'version','4','explicit new review is a new version');
select is(pg_temp.eligible(pg_temp.intent(3121,1,4))->>'eligible','false','new guardian review requires new explicit consent rather than reviving old consent');
select is(pg_temp.contact('grant_consent',3122,1,3229,pg_temp.consent_input(3121))->>'version','2','new consent captures renewed guardian review');
select is(pg_temp.eligible(pg_temp.intent(3121,2,4))->>'eligible','true','new consent and guardian versions both match');
select is(public.doctor_contact_history(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),'guardian',pg_temp.id(3120),0)->>'total','4','create/review/revoke/renew history retained');
select is(public.doctor_contact_history(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),'guardian',pg_temp.id(3120),0)#>>'{events,0,actor_user_id}',pg_temp.id(1)::text,'review history attributes actual stored owner actor');
select throws_ok($$select public.doctor_contact_history(pg_temp.practice(),pg_temp.location(),(pg_temp.v('contact_patient2')->>'patient_id')::uuid,'guardian',pg_temp.id(3120),0)$$,'42501','DOCTOR_ACCESS_DENIED','relationship history is bound to the selected patient');
select throws_ok($$select pg_temp.contact('create_contact',3130,0,3230,pg_temp.contact_input()||jsonb_build_object('recipient_kind','guardian','guardian_id',pg_temp.id(3120)),(pg_temp.v('contact_patient2')->>'patient_id')::uuid)$$,'42501','DOCTOR_ACCESS_DENIED','same phone cannot attach another patient guardian');
select pg_temp.claim(2);
select throws_ok($$select pg_temp.preferences()$$,'42501','DOCTOR_ACCESS_DENIED','independent practice owner cannot read contact records');
select pg_temp.claim(1);
select is(pg_temp.contact('revoke_contact',3100,1,3231,'{"source_ref":"Synthetic channel withdrawn"}')->>'version','2','contact channel revoked explicitly');
select is(pg_temp.eligible(pg_temp.intent(3100,3))->>'blocker','contact_unavailable','contact revocation suppresses already-prepared intent');
select throws_ok($$select pg_temp.contact('grant_consent',3110,2,3212,pg_temp.consent_input(3100))$$,'42501','DOCTOR_ACCESS_DENIED','receipt replay rechecks contact availability');
select throws_ok($$select * from public.patient_contact_channels$$,'42501',null,'direct destination table reads denied');
select throws_ok($$update public.patient_contact_events set details='{}'$$,'42501',null,'direct immutable history writes denied');
reset role;
-- Change only a run-owned fixture pair, never the database clock or event history.
update public.patient_guardian_relationships set reviewed_at=clock_timestamp()-interval'1 hour',expires_at=clock_timestamp()-interval'1 second'where id=pg_temp.id(3120);
set local role authenticated;select pg_temp.claim(1);
select is(pg_temp.eligible(pg_temp.intent(3121,2,4))->>'blocker','guardian_unavailable','expired guardian relationship suppresses a captured intent');
select is(public.doctor_contact_guardian_options(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),0,'')->>'total','0','expired relationships disappear from eligible options');
select public.doctor_archive_patient(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),1,pg_temp.id(3232));
select is(pg_temp.preferences()->>'can_write','false','archived patient blocks new contact/consent authority');
select is(pg_temp.preferences()->>'patient_archived','true','authorized archived history stays explicit');
select is(pg_temp.eligible(pg_temp.intent(3121,2,4))->>'blocker','patient_archived','patient archive suppresses previously prepared intent');
select is(pg_temp.contact('revoke_contact',3121,1,3233,'{"source_ref":"Synthetic archival reduction"}')->>'version','2','security reduction remains possible after patient archive');
select throws_ok($$select pg_temp.contact('create_contact',3131,0,3234,pg_temp.contact_input())$$,'42501','DOCTOR_ACCESS_DENIED','archived patient cannot gain a new contact');
reset role;
select is((select count(*)::integer from auth.users),5,'contacts and guardians never create Auth identities');
select ok(not exists(select 1 from public.patient_contact_events where details::text like'%15550001234%'),'operational history omits raw destinations');
select ok(not exists(select 1 from public.audit_events where event_type like'contact.%'and details::text like'%15550001234%'),'administrative audit omits raw destinations');
select ok(not has_function_privilege('service_role','public.doctor_contact_command(uuid,uuid,uuid,uuid,integer,text,jsonb,uuid)','execute'),'service clients gain no ambient contact mutation');
select ok(not has_function_privilege('authenticated','doctor_private.contact_eligibility(uuid,uuid,uuid,jsonb)','execute'),'raw policy helper is not exposed to clients');
select * from finish();rollback;
